const routeName = (id: string) => { const r = baseRoutes.find((item) => item.id === id); return r ? `${r.origin} → ${r.destination}` : id; };
const getStored = <T,>(key: string, fallback: T): T => {
  try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) as T : fallback; } catch { return fallback; }
};
function useStored<T>(key: string, fallback: T) {
  const [value, setValue] = useState<T>(() => getStored(key, fallback));
  useEffect(() => { localStorage.setItem(key, JSON.stringify(value)); }, [key, value]);
  return [value, setValue] as const;
}

function t(key: string, lang: Lang) { return labels[key]?.[lang] || labels[key]?.en || key; }
function Button({ children, onClick, variant = 'primary', className = '', type = 'button', disabled = false, testId }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'ghost' | 'danger'; className?: string; type?: 'button' | 'submit'; disabled?: boolean; testId: string }) {
  const styles = { primary: 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] hover:brightness-95', secondary: 'bg-[hsl(var(--secondary))] text-foreground hover:bg-[hsl(var(--secondary)/.75)]', ghost: 'text-muted-foreground hover:text-foreground hover:bg-[hsl(var(--muted))]', danger: 'bg-[hsl(var(--destructive)/.1)] text-[hsl(var(--destructive))] hover:bg-[hsl(var(--destructive)/.18)]' };
  return <button type={type} disabled={disabled} onClick={onClick || (() => window.alert('Demo action completed.'))} data-testid={testId} className={`inline-flex items-center justify-center gap-2 rounded-lg px-3.5 py-2 text-sm font-semibold transition disabled:pointer-events-none disabled:opacity-45 ${styles[variant]} ${className}`}>{children}</button>;
}
function StatusPill({ children, tone = 'neutral', testId }: { children: ReactNode; tone?: 'green' | 'amber' | 'red' | 'blue' | 'neutral'; testId: string }) {
  const tones = { green: 'bg-emerald-50 text-emerald-700 border-emerald-200', amber: 'bg-amber-50 text-amber-700 border-amber-200', red: 'bg-red-50 text-red-700 border-red-200', blue: 'bg-sky-50 text-sky-700 border-sky-200', neutral: 'bg-muted text-muted-foreground border-border' };
  return <span data-testid={testId} className={`inline-flex items-center gap-1.5 rounded-full border px-2 py-0.5 text-[11px] font-bold uppercase tracking-wide ${tones[tone]}`}><span className={`h-1.5 w-1.5 rounded-full ${tone === 'green' ? 'bg-emerald-500' : tone === 'amber' ? 'bg-amber-500' : tone === 'red' ? 'bg-red-500' : tone === 'blue' ? 'bg-sky-500' : 'bg-slate-400'}`} />{children}</span>;
}
function Metric({ label, value, note, icon: Icon, accent = 'teal', testId }: { label: string; value: string; note: string; icon: typeof Activity; accent?: 'teal' | 'orange' | 'blue' | 'slate'; testId: string }) {
  const color = { teal: 'bg-teal-50 text-teal-700', orange: 'bg-orange-50 text-orange-700', blue: 'bg-blue-50 text-blue-700', slate: 'bg-slate-100 text-slate-700' }[accent];
  return <div className="rounded-xl border bg-card p-4 shadow-sm" data-testid={`metric-${testId}`}><div className="flex items-start justify-between"><p className="text-xs font-semibold uppercase tracking-[.08em] text-muted-foreground">{label}</p><span className={`rounded-lg p-2 ${color}`}><Icon size={16} /></span></div><p data-testid={`value-${testId}`} className="mt-4 font-mono text-2xl font-bold tracking-tight">{value}</p><p className="mt-1 text-xs text-muted-foreground">{note}</p></div>;
}
